const listSavedViews = `-- name: ListSavedViews :many
SELECT v.id, v.uuid, v.workspace_id, v.actor_uuid, v.revision, v.name, v.resource, v.definition, v.columns, v.deleted, v.version, v.created_at, v.updated_at FROM saved_views v JOIN workspaces w ON w.id=v.workspace_id WHERE w.uuid=$1 AND v.actor_uuid=$2
 AND ($3::text='any' OR v.resource=$3) AND ($4::boolean OR NOT v.deleted)
 AND ($5::uuid='00000000-0000-0000-0000-000000000000'::uuid OR v.uuid>$5) ORDER BY v.uuid LIMIT $6
`

type ListSavedViewsParams struct {
	Uuid           uuid.UUID `json:"uuid"`
	ActorUuid      uuid.UUID `json:"actor_uuid"`
	Resource       string    `json:"resource"`
	IncludeDeleted bool      `json:"include_deleted"`
	AfterUuid      uuid.UUID `json:"after_uuid"`
	RowLimit       int32     `json:"row_limit"`
}

func (q *Queries) ListSavedViews(ctx context.Context, arg ListSavedViewsParams) ([]SavedView, error) {
	rows, err := q.db.Query(ctx, listSavedViews,
		arg.Uuid,
		arg.ActorUuid,
		arg.Resource,
		arg.IncludeDeleted,
		arg.AfterUuid,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SavedView{}
	for rows.Next() {
		var i SavedView
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.WorkspaceID,
			&i.ActorUuid,
			&i.Revision,
			&i.Name,
			&i.Resource,
			&i.Definition,
			&i.Columns,
			&i.Deleted,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

